def get_steam_trending_games(limit=None, cursor=None, captured_after=None, snapshot_id=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0065000" if __import__("os").path.isdir("./environment_mix/0065000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_steam_trending_games"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _to_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE"
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return "PARSE"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _dt_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            d = _to_dt(v)
            return None if isinstance(d, str) else d
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "INVALID"
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return "INVALID"
        if not isinstance(obj, dict):
            return "INVALID"
        if "after_rank" in obj and not isinstance(obj["after_rank"], int):
            return "INVALID"
        if "snapshot_id" in obj and not isinstance(obj["snapshot_id"], str):
            return "INVALID"
        return obj

    def _log(status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"gtm_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        })
        _save("request_logs.json", logs)

    try:
        if limit is None:
            limit = 100
        if not isinstance(limit, int):
            _log("VALIDATION_ERROR", "limit must be an integer")
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 200:
            _log("VALIDATION_ERROR", "limit must be between 1 and 200")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

        if cursor is not None and not isinstance(cursor, str):
            _log("VALIDATION_ERROR", "cursor must be a string")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

        cap_after_dt = None
        if captured_after is not None:
            d = _to_dt(captured_after)
            if d == "TYPE":
                _log("VALIDATION_ERROR", "captured_after must be a string")
                return _err("VALIDATION_ERROR", "captured_after must be a string", field="captured_after")
            if d == "PARSE":
                _log("VALIDATION_ERROR", "captured_after must be RFC3339 date-time")
                return _err("VALIDATION_ERROR", "captured_after must be RFC3339 date-time", field="captured_after")
            cap_after_dt = d

        if snapshot_id is not None:
            if not isinstance(snapshot_id, str):
                _log("VALIDATION_ERROR", "snapshot_id must be a string")
                return _err("VALIDATION_ERROR", "snapshot_id must be a string", field="snapshot_id")
            if not re.match(r"^gtm_snp_[0-9A-HJKMNP-TV-Z]{18,}$", snapshot_id):
                _log("VALIDATION_ERROR", "snapshot_id is invalid")
                return _err("VALIDATION_ERROR", "snapshot_id is invalid", field="snapshot_id")

        # Cursor is opaque; accept any string. Only validate if it matches our encoding.
        cur = _decode_cursor(cursor)
        if cur == "INVALID":
            cur = None  # relax: treat as "start" instead of rejecting
        after_rank = None
        cursor_snapshot_lock = None
        if isinstance(cur, dict):
            after_rank = cur.get("after_rank")
            cursor_snapshot_lock = cur.get("snapshot_id")

        nowdt = _now_utc()
        snaps = _load("trend_snapshots.json")
        if isinstance(snaps, dict) and "rows" in snaps:
            snaps = snaps.get("rows", [])
        if not isinstance(snaps, list):
            snaps = []

        def _is_expired(s):
            ex = _dt_row(s.get("expires_at"))
            return ex is not None and ex <= nowdt

        # Choose snapshot:
        chosen = None
        if snapshot_id is not None:
            for s in snaps:
                if isinstance(s, dict) and s.get("id") == snapshot_id:
                    chosen = s
                    break
            if chosen is None:
                _log("NOT_FOUND", "snapshot not found")
                return _err("NOT_FOUND", "snapshot not found", field="snapshot_id")
            # Must match endpoint mapping
            if chosen.get("platform") != "steam" or chosen.get("list_type") != "steam_trending":
                _log("VALIDATION_ERROR", "snapshot_id does not match steam_trending")
                return _err("VALIDATION_ERROR", "snapshot_id does not match steam_trending", field="snapshot_id")
            if chosen.get("status") != "ready":
                _log("NOT_FOUND", "snapshot is not ready")
                return _err("NOT_FOUND", "snapshot is not ready", field="snapshot_id")
            if _is_expired(chosen):
                _log("NOT_FOUND", "snapshot is expired")
                return _err("NOT_FOUND", "snapshot is expired", field="snapshot_id")
            if cap_after_dt is not None:
                cdt = _dt_row(chosen.get("captured_at"))
                if cdt is None or cdt < cap_after_dt:
                    chosen = None
        else:
            candidates = []
            for s in snaps:
                if not isinstance(s, dict):
                    continue
                if s.get("platform") != "steam" or s.get("list_type") != "steam_trending":
                    continue
                if s.get("status") != "ready":
                    continue
                if _is_expired(s):
                    continue
                if cap_after_dt is not None:
                    cdt = _dt_row(s.get("captured_at"))
                    if cdt is None or cdt < cap_after_dt:
                        continue
                candidates.append(s)
            candidates.sort(key=lambda r: (_dt_row(r.get("captured_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id", "")), reverse=True)
            chosen = candidates[0] if candidates else None

        if chosen is None:
            _log("ok", None)
            return {
                "snapshot": None,
                "items": [],
                "limit": limit,
                "next_cursor": None,
                "has_more": False
            }

        # If cursor encodes a snapshot_id, don't mix snapshots
        if cursor_snapshot_lock and cursor_snapshot_lock != chosen.get("id"):
            after_rank = None

        items = _load("trend_snapshot_items.json")
        if isinstance(items, dict) and "rows" in items:
            items = items.get("rows", [])
        if not isinstance(items, list):
            items = []

        games = _load("games.json")
        if isinstance(games, dict) and "rows" in games:
            games = games.get("rows", [])
        if not isinstance(games, list):
            games = []
        games_by_id = {g.get("id"): g for g in games if isinstance(g, dict) and isinstance(g.get("id"), str)}

        snapshot_items = []
        sid = chosen.get("id")
        for it in items:
            if not isinstance(it, dict):
                continue
            if it.get("snapshot_id") != sid:
                continue
            if it.get("status") != "active":
                continue
            rnk = it.get("rank")
            if not isinstance(rnk, int) or rnk < 1:
                continue
            if after_rank is not None and isinstance(after_rank, int) and rnk <= after_rank:
                continue
            g = games_by_id.get(it.get("game_id"))
            snapshot_items.append({
                "rank": rnk,
                "game": g,
                "item": it
            })

        snapshot_items.sort(key=lambda x: x["rank"])
        page = snapshot_items[:limit]
        has_more = len(snapshot_items) > len(page)
        next_cursor = None
        if has_more and page:
            next_cursor = _encode_cursor({"snapshot_id": sid, "after_rank": page[-1]["rank"]})

        _log("ok", None)
        return {
            "snapshot": chosen,
            "items": page,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    except Exception as e:
        _log("VALIDATION_ERROR", "internal_error")
        return _err("VALIDATION_ERROR", "internal_error", detail=str(e))

