        return _err("VALIDATION_ERROR", "limit out of range (1-200)", field="limit")

    cap_after_dt = None
    if captured_after is not None:
        if not isinstance(captured_after, str):
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "captured_after must be an RFC3339 string", field="captured_after")
        cap_after_dt = _parse_rfc3339(captured_after)
        if cap_after_dt is None:
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "captured_after must be a valid RFC3339 date-time", field="captured_after")

    cur_obj = None
    if cursor is not None:
        if not isinstance(cursor, str):
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        cur_obj = _decode_cursor(cursor)
        if cur_obj is None:
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if cur_obj.get("v") != 1 or cur_obj.get("endpoint") != endpoint:
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "cursor is not valid for this endpoint", field="cursor")
        if not isinstance(cur_obj.get("offset"), int) or cur_obj["offset"] < 0:
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "cursor offset is invalid", field="cursor")
        # cursor locks in the query shape
        if cur_obj.get("platform") != platform or cur_obj.get("list_type") != list_type or cur_obj.get("captured_after") != (captured_after or None):
            status_code = "validation_error"
            return _err("VALIDATION_ERROR", "cursor does not match request parameters", field="cursor")

    # validate incompatible combos (platform + list_type)
    steam_types = {"steam_trending", "steam_top_sellers", "steam_most_played"}
    epic_types = {"epic_free_games", "epic_trending"}
    if platform == "steam" and list_type in epic_types:
        status_code = "validation_error"
        return _err("VALIDATION_ERROR", "platform 'steam' is incompatible with requested list_type", field="list_type")
    if platform == "epic" and list_type in steam_types:
        status_code = "validation_error"
        return _err("VALIDATION_ERROR", "platform 'epic' is incompatible with requested list_type", field="list_type")

    nowdt = _now()
    snapshots = _load("trend_snapshots.json")
    items = _load("trend_snapshot_items.json")
    games = _load("games.json")
    game_by_id = {g.get("id"): g for g in games if isinstance(g, dict) and g.get("id") is not None}

    # decide which list types to include
    include_types = []
    if list_type == "all":
        include_types = list(valid_list_types[:-1])
    else:
        include_types = [list_type]
    if platform == "steam":
        include_types = [t for t in include_types if t in steam_types]
    elif platform == "epic":
        include_types = [t for t in include_types if t in epic_types]

    # pick latest ready snapshot per list_type (do not mix within list_type)
    chosen_by_type = {}
    for lt in include_types:
        candidates = []
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "ready":
                continue
            if s.get("list_type") != lt:
                continue
            # platform implied by list_type
            if lt in steam_types and s.get("platform") != "steam":
                continue
            if lt in epic_types and s.get("platform") != "epic":
                continue
            if _is_expired(s, nowdt):
                continue
            cap_dt = _dt(s.get("captured_at"))
            if cap_dt is None:
                continue
            if cap_after_dt is not None and cap_dt < cap_after_dt:
                continue
            # additional rule: steam_most_played source constraint
            if lt == "steam_most_played" and s.get("source") not in ("steamcharts", "multi"):
                continue
            candidates.append((cap_dt, s))
        candidates.sort(key=lambda x: x[0], reverse=True)
        if candidates:
            chosen_by_type[lt] = candidates[0][1]

    # build a flattened list of entries; stable ordering:
    # list_type order then rank asc. Include snapshot metadata per entry.
    type_order = {t: i for i, t in enumerate(include_types)}
    flat = []
    for lt, snap in chosen_by_type.items():
        sid = snap.get("id")
        snap_items = [it for it in items if isinstance(it, dict) and it.get("snapshot_id") == sid and it.get("status") == "active"]
        snap_items.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id", "")))
        for it in snap_items:
            g = game_by_id.get(it.get("game_id"))
            flat.append({
                "list_type": lt,
                "platform": snap.get("platform"),
                "snapshot": {
                    "id": sid,
                    "captured_at": snap.get("captured_at"),
                    "expires_at": snap.get("expires_at"),
                    "source": snap.get("source"),
                    "status": snap.get("status"),
                },
                "item": {
                    "id": it.get("id"),
                    "rank": it.get("rank"),
                    "game_id": it.get("game_id"),
                    "game": g,
                    "platform_game_key": it.get("platform_game_key"),
                    "title": it.get("title_override") or (g.get("canonical_title") if isinstance(g, dict) else None),
                    "price_amount": it.get("price_amount"),
                    "price_currency": it.get("price_currency"),
                    "discount_percent": it.get("discount_percent"),
                    "is_free": it.get("is_free"),
                    "promo_starts_at": it.get("promo_starts_at"),
                    "promo_ends_at": it.get("promo_ends_at"),
                    "current_players": it.get("current_players"),
                    "peak_players_24h": it.get("peak_players_24h"),
                }
            })

    flat.sort(key=lambda e: (type_order.get(e["list_type"], 10**9), e["item"].get("rank") if isinstance(e["item"].get("rank"), int) else 10**9, e["item"].get("id", "")))

    offset = cur_obj["offset"] if cur_obj else 0
    total = len(flat)
    page = flat[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({
        "v": 1,
        "endpoint": endpoint,
        "offset": next_offset,
        "platform": platform,
        "list_type": list_type,
        "captured_after": captured_after or None
    }) if has_more else None

    body = {
        "filters": {"platform": platform, "list_type": list_type, "captured_after": captured_after},
        "snapshots": {lt: (chosen_by_type[lt] if lt in chosen_by_type else None) for lt in include_types},
        "entries": page,
        "pagination": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    }

    # audit log best-effort
    try:
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"gtm_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "timestamp": nowdt.isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
    except Exception:
        pass

    return body

def get_api_health(include_details=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0065000" if __import__("os").path.isdir("./environment_mix/0065000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_api_health"
    status_code = "ok"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            return _parse_rfc3339(v)
        return None

    if include_details is None:
        include_details = False
    if not isinstance(include_details, bool):
        status_code = "validation_error"
        return _err("VALIDATION_ERROR", "include_details must be boolean", field="include_details")

    nowdt = _now()
    checks = _load("health_checks.json")
    # most recent by checked_at desc
    best = None
    best_dt = None
    for r in checks:
        if not isinstance(r, dict):
            continue
        d = _dt(r.get("checked_at"))
        if d is None:
            continue
        if best is None or d > best_dt:
            best = r
            best_dt = d

    # compute last_successful_snapshot_at from trend_snapshots (ready, non-expired) if not present
    snaps = _load("trend_snapshots.json")
    last_ready_dt = None
    for s in snaps:
        if not isinstance(s, dict):
            continue
        if s.get("status") != "ready":
            continue
        ex = _dt(s.get("expires_at"))
        if ex is not None and ex <= nowdt:
            continue
        cap = _dt(s.get("captured_at"))
        if cap is None:
            continue
        if last_ready_dt is None or cap > last_ready_dt:
            last_ready_dt = cap

    freshness_window = datetime.timedelta(minutes=30)

    if best is None:
        derived = {
            "status": "degraded",
            "checked_at": None,
            "steam_ok": False,
            "epic_ok": False,
            "last_successful_snapshot_at": last_ready_dt.isoformat() if last_ready_dt else None,
            "details": {"reason": "no_health_data"} if include_details else None
        }
    else:
        steam_ok = bool(best.get("steam_ok"))
        epic_ok = bool(best.get("epic_ok"))
        last_success = _dt(best.get("last_successful_snapshot_at"))
        if last_success is None:
            last_success = last_ready_dt
        fresh = (last_success is not None and (nowdt - last_success) <= freshness_window)

        if steam_ok and epic_ok and fresh:
            computed_status = "ok"
        else:
            if (not steam_ok) and (not epic_ok):
                computed_status = "down"
            else:
                computed_status = "degraded"

        details = None
        if include_details:
            details = best.get("details")
            if details is None:
                details = {}
            if isinstance(details, dict):
                details = dict(details)
                details.setdefault("freshness_window_minutes", 30)
                details["fresh_snapshot"] = fresh
                if last_success is None:
                    details["snapshot_reason"] = "no_ready_snapshot"
            else:
                details = {"raw_details": details, "freshness_window_minutes": 30, "fresh_snapshot": fresh}

        derived = {
            "status": computed_status,
            "checked_at": best.get("checked_at"),
            "steam_ok": steam_ok,
            "epic_ok": epic_ok,
            "last_successful_snapshot_at": last_success.isoformat() if last_success else None,
            "details": details
        }

    # audit log best-effort
    try:
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"gtm_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "timestamp": nowdt.isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
    except Exception:
        pass

    return derived

def list_games(limit=None, cursor=None, query=None, status=None, primary_platform=None, steam_app_id=None, epic_offer_id=None, merged_into_game_id=None, updated_after=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0065000" if __import__("os").path.isdir("./environment_mix/0065000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_games"

    def _to_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE"
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return "PARSE"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _dt_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            d = _to_dt(v)
            return None if isinstance(d, str) else d
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "INVALID"
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return "INVALID"
        if not isinstance(obj, dict):
            return "INVALID"
        if "updated_at" in obj and not isinstance(obj["updated_at"], str):
            return "INVALID"
        if "id" in obj and not isinstance(obj["id"], str):
            return "INVALID"
        return obj

    def _log(status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"gtm_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        })
        _save("request_logs.json", logs)

    try:
        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            _log("VALIDATION_ERROR", "limit must be an integer")
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 200:
            _log("VALIDATION_ERROR", "limit must be between 1 and 200")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

        if cursor is not None and not isinstance(cursor, str):
            _log("VALIDATION_ERROR", "cursor must be a string")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

        if query is not None:
            if not isinstance(query, str):
                _log("VALIDATION_ERROR", "query must be a string")
                return _err("VALIDATION_ERROR", "query must be a string", field="query")
            q = query.strip()
            if len(q) < 1 or len(q) > 200:
                _log("VALIDATION_ERROR", "query length out of range")
                return _err("VALIDATION_ERROR", "query length out of range", field="query")
            query_l = q.lower()
        else:
            query_l = None

        if status is not None and status not in ("active", "merged", "disabled"):
            _log("VALIDATION_ERROR", "status is invalid")
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

        if primary_platform is not None and primary_platform not in ("steam", "epic"):
            _log("VALIDATION_ERROR", "primary_platform is invalid")
            return _err("VALIDATION_ERROR", "primary_platform is invalid", field="primary_platform")

        if steam_app_id is not None:
            if not isinstance(steam_app_id, int):
                _log("VALIDATION_ERROR", "steam_app_id must be an integer")
                return _err("VALIDATION_ERROR", "steam_app_id must be an integer", field="steam_app_id")
            if steam_app_id < 1:
                _log("VALIDATION_ERROR", "steam_app_id must be >= 1")
                return _err("VALIDATION_ERROR", "steam_app_id must be >= 1", field="steam_app_id")

        if epic_offer_id is not None:
            if not isinstance(epic_offer_id, str):
                _log("VALIDATION_ERROR", "epic_offer_id must be a string")
                return _err("VALIDATION_ERROR", "epic_offer_id must be a string", field="epic_offer_id")
            eo = epic_offer_id.strip()
            if len(eo) < 1 or len(eo) > 200:
                _log("VALIDATION_ERROR", "epic_offer_id length out of range")
                return _err("VALIDATION_ERROR", "epic_offer_id length out of range", field="epic_offer_id")
            epic_offer_id = eo

        if merged_into_game_id is not None:
            if not isinstance(merged_into_game_id, str):
                _log("VALIDATION_ERROR", "merged_into_game_id must be a string")
                return _err("VALIDATION_ERROR", "merged_into_game_id must be a string", field="merged_into_game_id")
            if not re.match(r"^gtm_gam_[0-9A-HJKMNP-TV-Z]{18,}$", merged_into_game_id):
                _log("VALIDATION_ERROR", "merged_into_game_id is invalid")
                return _err("VALIDATION_ERROR", "merged_into_game_id is invalid", field="merged_into_game_id")
            if status is not None and status != "merged":
                _log("VALIDATION_ERROR", "merged_into_game_id requires status='merged'")
                return _err("VALIDATION_ERROR", "merged_into_game_id requires status='merged'", field="merged_into_game_id")

        upd_after_dt = None
        if updated_after is not None:
            d = _to_dt(updated_after)
            if d == "TYPE":
                _log("VALIDATION_ERROR", "updated_after must be a string")
                return _err("VALIDATION_ERROR", "updated_after must be a string", field="updated_after")
            if d == "PARSE":
                _log("VALIDATION_ERROR", "updated_after must be RFC3339 date-time")
                return _err("VALIDATION_ERROR", "updated_after must be RFC3339 date-time", field="updated_after")
            upd_after_dt = d

        cur = _decode_cursor(cursor)
        if cur == "INVALID":
            cur = None
        after_updated_at = None
        after_id = None
        if isinstance(cur, dict):
            after_updated_at = cur.get("updated_at")
            after_id = cur.get("id")
            if after_updated_at is not None and not isinstance(after_updated_at, str):
                after_updated_at = None
            if after_id is not None and not isinstance(after_id, str):
                after_id = None

        rows = _load("games.json")
        if isinstance(rows, dict) and "rows" in rows:
            rows = rows.get("rows", [])
        if not isinstance(rows, list):
            rows = []

        # Filter
        out = []
        for g in rows:
            if not isinstance(g, dict):
                continue
            if status is not None and g.get("status") != status:
                continue
            if primary_platform is not None and g.get("primary_platform") != primary_platform:
                continue
            if steam_app_id is not None and g.get("steam_app_id") != steam_app_id:
                continue
            if epic_offer_id is not None and g.get("epic_offer_id") != epic_offer_id:
                continue
            if merged_into_game_id is not None and g.get("merged_into_game_id") != merged_into_game_id:
                continue
            if query_l is not None:
                ct = g.get("canonical_title") or ""
                sl = g.get("slug") or ""
                if not isinstance(ct, str):
                    ct = str(ct)
                if not isinstance(sl, str):
                    sl = str(sl)
                if query_l not in ct.lower() and query_l not in sl.lower():
                    continue
            if upd_after_dt is not None:
                u = _dt_row(g.get("updated_at"))
                if u is None or u < upd_after_dt:
                    continue
            out.append(g)

        # Sort by updated_at desc, id desc tiebreaker
        out.sort(key=lambda r: (_dt_row(r.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id", "")), reverse=True)

        # Apply cursor (seek pagination)
        if after_updated_at and after_id:
            after_dt = _dt_row(after_updated_at)
            if after_dt is not None:
                filtered = []
                for g in out:
                    gdt = _dt_row(g.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                    gid = g.get("id", "")
                    if (gdt < after_dt) or (gdt == after_dt and gid < after_id):
                        filtered.append(g)
                out = filtered

        page = out[:limit]
        has_more = len(out) > len(page)
        next_cursor = None
        if has_more and page:
            last = page[-1]
            next_cursor = _encode_cursor({"updated_at": last.get("updated_at"), "id": last.get("id")})

        _log("ok", None)
        return {
            "games": page,
            "limit": limit,
            "total": len(out),
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    except Exception as e:
        _log("VALIDATION_ERROR", "internal_error")
        return _err("VALIDATION_ERROR", "internal_error", detail=str(e))

def get_game(game_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0065000" if __import__("os").path.isdir("./environment_mix/0065000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_game"
    status = "ok"

    # usage/audit log (best-effort schema discovery)
    def _log_call(status_code, message=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"gtm_req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate input
    if not isinstance(game_id, str):
        status = "validation_error"
        _log_call("VALIDATION_ERROR", "game_id must be a string")
        return _err("VALIDATION_ERROR", "game_id must be a string")
    if not re.match(r"^gtm_gam_[0-9A-HJKMNP-TV-Z]{18,}$", game_id):
        status = "validation_error"
        _log_call("VALIDATION_ERROR", "game_id format is invalid")
        return _err("VALIDATION_ERROR", "game_id format is invalid")

    games = _load("games.json")
    if not isinstance(games, list):
        games = []

    game = next((g for g in games if isinstance(g, dict) and g.get("id") == game_id), None)
    if not game:
        status = "not_found"
        _log_call("NOT_FOUND", "game not found")
        return _err("NOT_FOUND", "Game not found")

    _log_call("OK")
    return {"game": game}

def update_game(game_id, canonical_title=None, slug=None, primary_platform=None, steam_app_id=None, epic_offer_id=None, header_image_url=None, store_url=None, status=None, merged_into_game_id=None, **_extra):
    import json, os, datetime, re, time, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0065000" if __import__("os").path.isdir("./environment_mix/0065000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_game"

    def _log_call(status_code, message=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"gtm_req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _is_rfc3339_uri(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    # Validate required
    if not isinstance(game_id, str):
        _log_call("VALIDATION_ERROR", "game_id must be a string")
        return _err("VALIDATION_ERROR", "game_id must be a string")
    if not re.match(r"^gtm_gam_[0-9A-HJKMNP-TV-Z]{18,}$", game_id):
        _log_call("VALIDATION_ERROR", "game_id format is invalid")
        return _err("VALIDATION_ERROR", "game_id format is invalid")

    # Validate optional fields per tool schema
    if canonical_title is not None:
        if not isinstance(canonical_title, str):
            _log_call("VALIDATION_ERROR", "canonical_title must be a string")
            return _err("VALIDATION_ERROR", "canonical_title must be a string")
        if len(canonical_title) < 1 or len(canonical_title) > 200:
            _log_call("VALIDATION_ERROR", "canonical_title length out of range")
            return _err("VALIDATION_ERROR", "canonical_title length out of range")
    if slug is not None:
        if not isinstance(slug, str):
            _log_call("VALIDATION_ERROR", "slug must be a string")
            return _err("VALIDATION_ERROR", "slug must be a string")
        if len(slug) < 1 or len(slug) > 200:
            _log_call("VALIDATION_ERROR", "slug length out of range")
            return _err("VALIDATION_ERROR", "slug length out of range")
        if not re.match(r"^[a-z0-9]+(?:-[a-z0-9]+)*$", slug):
            _log_call("VALIDATION_ERROR", "slug format is invalid")
            return _err("VALIDATION_ERROR", "slug format is invalid")
    if primary_platform is not None:
        if primary_platform not in ("steam", "epic"):
            _log_call("VALIDATION_ERROR", "primary_platform must be one of: steam, epic")
            return _err("VALIDATION_ERROR", "primary_platform must be one of: steam, epic")
    if steam_app_id is not None:
        if not isinstance(steam_app_id, int):
            _log_call("VALIDATION_ERROR", "steam_app_id must be an integer")
            return _err("VALIDATION_ERROR", "steam_app_id must be an integer")
        if steam_app_id < 1:
            _log_call("VALIDATION_ERROR", "steam_app_id must be >= 1")
            return _err("VALIDATION_ERROR", "steam_app_id must be >= 1")
    if epic_offer_id is not None:
        if not isinstance(epic_offer_id, str):
            _log_call("VALIDATION_ERROR", "epic_offer_id must be a string")
            return _err("VALIDATION_ERROR", "epic_offer_id must be a string")
        if len(epic_offer_id) < 1 or len(epic_offer_id) > 200:
            _log_call("VALIDATION_ERROR", "epic_offer_id length out of range")
            return _err("VALIDATION_ERROR", "epic_offer_id length out of range")
    if header_image_url is not None and not _is_rfc3339_uri(header_image_url):
        _log_call("VALIDATION_ERROR", "header_image_url must be a valid http(s) URI")
        return _err("VALIDATION_ERROR", "header_image_url must be a valid http(s) URI")
    if store_url is not None and not _is_rfc3339_uri(store_url):
        _log_call("VALIDATION_ERROR", "store_url must be a valid http(s) URI")
        return _err("VALIDATION_ERROR", "store_url must be a valid http(s) URI")
    if status is not None:
        if status not in ("active", "merged", "disabled"):
            _log_call("VALIDATION_ERROR", "status must be one of: active, merged, disabled")
            return _err("VALIDATION_ERROR", "status must be one of: active, merged, disabled")
    if merged_into_game_id is not None:
        if not isinstance(merged_into_game_id, str):
            _log_call("VALIDATION_ERROR", "merged_into_game_id must be a string")
            return _err("VALIDATION_ERROR", "merged_into_game_id must be a string")
        if not re.match(r"^gtm_gam_[0-9A-HJKMNP-TV-Z]{18,}$", merged_into_game_id):
            _log_call("VALIDATION_ERROR", "merged_into_game_id format is invalid")
            return _err("VALIDATION_ERROR", "merged_into_game_id format is invalid")

    games = _load("games.json")
    if not isinstance(games, list):
        games = []

    idx = None
    for i, g in enumerate(games):
        if isinstance(g, dict) and g.get("id") == game_id:
            idx = i
            break
    if idx is None:
        _log_call("NOT_FOUND", "game not found")
        return _err("NOT_FOUND", "Game not found")

    game = games[idx]
    old_status = game.get("status")

    # Enforce lifecycle transitions if status is provided
    transitions = {
        "active": set(["merged", "disabled"]),
        "merged": set([]),
        "disabled": set(["active"]),
    }
    if old_status not in transitions:
        _log_call("CONFLICT", "game has invalid stored status")
        return _err("CONFLICT", "Stored game status is invalid", stored_status=old_status)

    if status is not None and status != old_status:
        if status not in transitions.get(old_status, set()):
            _log_call("INVALID_TRANSITION", f"cannot transition status from {old_status} to {status}")
            return _err("INVALID_TRANSITION", f"Cannot transition status from {old_status} to {status}",
                        from_status=old_status, to_status=status)

    # Apply updates to a copy to validate constraints before saving
    updated = dict(game)
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    mutable_fields = {
        "canonical_title": canonical_title,
        "slug": slug,
        "primary_platform": primary_platform,
        "steam_app_id": steam_app_id,
        "epic_offer_id": epic_offer_id,
        "header_image_url": header_image_url,
        "store_url": store_url,
        "status": status,
        "merged_into_game_id": merged_into_game_id,
    }
    for k, v in mutable_fields.items():
        if v is not None:
            updated[k] = v

    # Business/schema constraints
    # - primary_platform enum in store schema includes 'unknown', but tool only allows steam/epic; accept stored unknown if not updating.
    if updated.get("primary_platform") is not None and updated.get("primary_platform") not in ("steam", "epic", "unknown"):
        _log_call("VALIDATION_ERROR", "primary_platform is invalid")
        return _err("VALIDATION_ERROR", "primary_platform is invalid")

    # - steam_app_id null or > 0 already validated if provided
    sa = updated.get("steam_app_id")
    if sa is not None:
        if not isinstance(sa, int):
            _log_call("VALIDATION_ERROR", "steam_app_id must be an integer")
            return _err("VALIDATION_ERROR", "steam_app_id must be an integer")
        if sa <= 0:
            _log_call("VALIDATION_ERROR", "steam_app_id must be > 0")
            return _err("VALIDATION_ERROR", "steam_app_id must be > 0")

    # - unique(slug)
    if updated.get("slug") is None or not isinstance(updated.get("slug"), str) or not updated.get("slug"):
        _log_call("VALIDATION_ERROR", "slug is required and must be non-empty")
        return _err("VALIDATION_ERROR", "slug is required and must be non-empty")
    for g in games:
        if isinstance(g, dict) and g.get("id") != game_id and g.get("slug") == updated.get("slug"):
            _log_call("CONFLICT", "slug must be unique")
            return _err("CONFLICT", "slug must be unique", field="slug")

    # - unique(steam_app_id) where not null
    if updated.get("steam_app_id") is not None:
        for g in games:
            if isinstance(g, dict) and g.get("id") != game_id and g.get("steam_app_id") == updated.get("steam_app_id"):
                _log_call("CONFLICT", "steam_app_id must be unique")
                return _err("CONFLICT", "steam_app_id must be unique", field="steam_app_id")

    # - unique(epic_offer_id) where not null
    if updated.get("epic_offer_id") is not None:
        for g in games:
            if isinstance(g, dict) and g.get("id") != game_id and g.get("epic_offer_id") == updated.get("epic_offer_id"):
                _log_call("CONFLICT", "epic_offer_id must be unique")
                return _err("CONFLICT", "epic_offer_id must be unique", field="epic_offer_id")

    # - merged constraints
    new_status = updated.get("status")
    if new_status == "merged":
        mid = updated.get("merged_into_game_id")
        if mid is None:
            _log_call("VALIDATION_ERROR", "merged_into_game_id is required when status='merged'")
            return _err("VALIDATION_ERROR", "merged_into_game_id is required when status='merged'",
                        field="merged_into_game_id")
        if mid == game_id:
            _log_call("VALIDATION_ERROR", "merged_into_game_id must be different from game_id")
            return _err("VALIDATION_ERROR", "merged_into_game_id must be different from game_id")
        target = next((g for g in games if isinstance(g, dict) and g.get("id") == mid), None)
        if not target:
            _log_call("NOT_FOUND", "merged_into_game_id does not exist")
            return _err("NOT_FOUND", "merged_into_game_id does not exist", merged_into_game_id=mid)
    else:
        if updated.get("merged_into_game_id") is not None:
            _log_call("VALIDATION_ERROR", "merged_into_game_id must be null unless status='merged'")
            return _err("VALIDATION_ERROR", "merged_into_game_id must be null unless status='merged'")

    # Update timestamps
    updated["updated_at"] = now
    if "created_at" not in updated or not updated.get("created_at"):
        updated["created_at"] = now

    # Persist
    games[idx] = updated
    _save("games.json", games)

    _log_call("OK")
    return {"game": updated}

def list_trend_snapshots(limit=None, cursor=None, platform=None, list_type=None, status=None, captured_after=None, captured_before=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0065000" if __import__("os").path.isdir("./environment_mix/0065000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_trend_snapshots"

    def _to_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE"
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return "PARSE"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _dt_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            d = _to_dt(v)
            return None if isinstance(d, str) else d
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "INVALID"
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return "INVALID"
        if not isinstance(obj, dict):
            return "INVALID"
        if "captured_at" in obj and not isinstance(obj["captured_at"], str):
            return "INVALID"
        if "id" in obj and not isinstance(obj["id"], str):
            return "INVALID"
        return obj

    def _log(status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"gtm_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        })
        _save("request_logs.json", logs)

    try:
        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            _log("VALIDATION_ERROR", "limit must be an integer")
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 200:
            _log("VALIDATION_ERROR", "limit must be between 1 and 200")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            _log("VALIDATION_ERROR", "cursor must be a string")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

        if platform is not None and platform not in ("steam", "epic"):
            _log("VALIDATION_ERROR", "platform is invalid")
            return _err("VALIDATION_ERROR", "platform is invalid", field="platform")

        allowed_list_types = ("steam_trending", "steam_top_sellers", "steam_most_played", "epic_free_games", "epic_trending")
        if list_type is not None and list_type not in allowed_list_types:
            _log("VALIDATION_ERROR", "list_type is invalid")
            return _err("VALIDATION_ERROR", "list_type is invalid", field="list_type")

        if platform == "steam" and list_type is not None and list_type not in ("steam_trending", "steam_top_sellers", "steam_most_played"):
            _log("VALIDATION_ERROR", "list_type not valid for platform steam")
            return _err("VALIDATION_ERROR", "list_type not valid for platform steam", field="list_type")

        if platform == "epic" and list_type is not None and list_type not in ("epic_free_games", "epic_trending"):
            _log("VALIDATION_ERROR", "list_type not valid for platform epic")
            return _err("VALIDATION_ERROR", "list_type not valid for platform epic", field="list_type")

        if status is not None and status not in ("capturing", "ready", "stale", "failed"):
            _log("VALIDATION_ERROR", "status is invalid")
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

        cap_after_dt = None
        if captured_after is not None:
            d = _to_dt(captured_after)
            if d == "TYPE":
                _log("VALIDATION_ERROR", "captured_after must be a string")
                return _err("VALIDATION_ERROR", "captured_after must be a string", field="captured_after")
            if d == "PARSE":
                _log("VALIDATION_ERROR", "captured_after must be RFC3339 date-time")
                return _err("VALIDATION_ERROR", "captured_after must be RFC3339 date-time", field="captured_after")
            cap_after_dt = d

        cap_before_dt = None
        if captured_before is not None:
            d = _to_dt(captured_before)
            if d == "TYPE":
                _log("VALIDATION_ERROR", "captured_before must be a string")
                return _err("VALIDATION_ERROR", "captured_before must be a string", field="captured_before")
            if d == "PARSE":
                _log("VALIDATION_ERROR", "captured_before must be RFC3339 date-time")
                return _err("VALIDATION_ERROR", "captured_before must be RFC3339 date-time", field="captured_before")
            cap_before_dt = d

        cur = _decode_cursor(cursor)
        if cur == "INVALID":
            cur = None
        after_captured_at = None
        after_id = None
        if isinstance(cur, dict):
            after_captured_at = cur.get("captured_at")
            after_id = cur.get("id")

        rows = _load("trend_snapshots.json")
        if isinstance(rows, dict) and "rows" in rows:
            rows = rows.get("rows", [])
        if not isinstance(rows, list):
            rows = []

        out = []
        for s in rows:
            if not isinstance(s, dict):
                continue
            if platform is not None and s.get("platform") != platform:
                continue
            if list_type is not None and s.get("list_type") != list_type:
                continue
            if status is not None and s.get("status") != status:
                continue
            cdt = _dt_row(s.get("captured_at"))
            if cap_after_dt is not None:
                if cdt is None or cdt < cap_after_dt:
                    continue
            if cap_before_dt is not None:
                if cdt is not None and cdt >= cap_before_dt:
                    continue
            out.append(s)

        out.sort(key=lambda r: (_dt_row(r.get("captured_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id", "")), reverse=True)

        if after_captured_at and after_id and isinstance(after_captured_at, str) and isinstance(after_id, str):
            after_dt = _dt_row(after_captured_at)
            if after_dt is not None:
                filtered = []
                for s in out:
                    sdt = _dt_row(s.get("captured_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                    sid = s.get("id", "")
                    if (sdt < after_dt) or (sdt == after_dt and sid < after_id):
                        filtered.append(s)
                out = filtered

        page = out[:limit]
        has_more = len(out) > len(page)
        next_cursor = None
        if has_more and page:
            last = page[-1]
            next_cursor = _encode_cursor({"captured_at": last.get("captured_at"), "id": last.get("id")})

        _log("ok", None)
        return {
            "snapshots": page,
            "limit": limit,
            "total": len(out),
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    except Exception as e:
        _log("VALIDATION_ERROR", "internal_error")
        return _err("VALIDATION_ERROR", "internal_error", detail=str(e))
